const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const kabulp = ee.Geometry.Point([69.2075, 34.5553]);
    const radius_m = 30 * 1609.34; // 30 miles
    const region = kabulp.buffer(radius_m);

    const period2017 = {start: '2017-02-01', end: '2017-03-01'};
    const period2018 = {start: '2018-02-01', end: '2018-03-01'};

    // Helper to load monthly LST (with fallbacks) and return image + metadata
    function getMonthlyLST(region, start, end) {
      // Try MODIS Terra monthly CMG
      try {
        let col = ee.ImageCollection('MODIS/061/MOD11C3').filterDate(start, end);
        let size = col.size().getInfo();
        if (size > 0) {
          let img = ee.Image(col.first());
          let lst = img.select('LST_Day_CMG');
          let qc = img.select('QC_Day');
          let isGood = qc.bitwiseAnd(3).lt(2); // bits 0-1: 0 or 1
          let masked = lst.updateMask(lst.gt(0).and(isGood)).multiply(0.02).rename('LST_K');
          return {image: masked, source: 'MOD11C3', images: size, scale: 5000};
        }
      } catch (e) {}

      // Fallback: MODIS Terra 8-day 1km
      try {
        let col = ee.ImageCollection('MODIS/061/MOD11A2').filterDate(start, end);
        let size = col.size().getInfo();
        if (size > 0) {
          let colMasked = col.map(function(i) {
            let lst = i.select('LST_Day_1km');
            let qc = i.select('QC_Day');
            let isGood = qc.bitwiseAnd(3).lt(2);
            return lst.updateMask(lst.gt(0).and(isGood));
          });
          let mean = colMasked.mean().multiply(0.02).rename('LST_K');
          return {image: mean, source: 'MOD11A2', images: size, scale: 3000};
        }
      } catch (e) {}

      // Fallback: MODIS Aqua monthly CMG
      try {
        let col = ee.ImageCollection('MODIS/061/MYD11C3').filterDate(start, end);
        let size = col.size().getInfo();
        if (size > 0) {
          let img = ee.Image(col.first());
          let lst = img.select('LST_Day_CMG');
          let qc = img.select('QC_Day');
          let isGood = qc.bitwiseAnd(3).lt(2);
          let masked = lst.updateMask(lst.gt(0).and(isGood)).multiply(0.02).rename('LST_K');
          return {image: masked, source: 'MYD11C3', images: size, scale: 5000};
        }
      } catch (e) {}

      // Fallback: MODIS Aqua 8-day 1km
      try {
        let col = ee.ImageCollection('MODIS/061/MYD11A2').filterDate(start, end);
        let size = col.size().getInfo();
        if (size > 0) {
          let colMasked = col.map(function(i) {
            let lst = i.select('LST_Day_1km');
            let qc = i.select('QC_Day');
            let isGood = qc.bitwiseAnd(3).lt(2);
            return lst.updateMask(lst.gt(0).and(isGood));
          });
          let mean = colMasked.mean().multiply(0.02).rename('LST_K');
          return {image: mean, source: 'MYD11A2', images: size, scale: 3000};
        }
      } catch (e) {}

      return {image: null, source: null, images: 0, scale: 3000};
    }

    function statsFor(img, region, scale) {
      const band = 'LST_K';
      const validCount = img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get(band);
      const totalCount = ee.Image(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('ones');
      const meanK = img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get(band);
      return {
        validCount: validCount,
        totalCount: totalCount,
        meanK: meanK
      };
    }

    // Acquire data
    const feb2017 = getMonthlyLST(region, period2017.start, period2017.end);
    const feb2018 = getMonthlyLST(region, period2018.start, period2018.end);

    if (feb2017.images === 0 || feb2018.images === 0) {
      console.log('2017 Images:', feb2017.images, '2018 Images:', feb2018.images);
      console.log('Empty collection for one or both periods.');
      console.log('C1: Empty Collection');
      console.log('C1');
      return;
    }

    // Compute stats
    const s2017 = statsFor(feb2017.image, region, feb2017.scale);
    const s2018 = statsFor(feb2018.image, region, feb2018.scale);

    const valid2017 = ee.Number(s2017.validCount).getInfo();
    const total2017 = ee.Number(s2017.totalCount).getInfo();
    const meanK2017 = s2017.meanK.getInfo();

    const valid2018 = ee.Number(s2018.validCount).getInfo();
    const total2018 = ee.Number(s2018.totalCount).getInfo();
    const meanK2018 = s2018.meanK.getInfo();

    // Valid pixel checks
    if ((!valid2017 || valid2017 === 0) || (!valid2018 || valid2018 === 0)) {
      console.log(`2017 ValidPx: ${valid2017 || 0}/${total2017 || 0}`);
      console.log(`2018 ValidPx: ${valid2018 || 0}/${total2018 || 0}`);
      console.log('No valid pixels after masking.');
      console.log('C2: No Valid Pixels');
      console.log('C2');
      return;
    }

    // Calculation validity checks
    if (meanK2017 === null || meanK2018 === null || isNaN(meanK2017) || isNaN(meanK2018)) {
      console.log('Calculation failure: mean is null/NaN.');
      console.log('C3: Calculation Failure');
      console.log('C3');
      return;
    }

    const meanC2017 = meanK2017 - 273.15;
    const meanC2018 = meanK2018 - 273.15;

    if (meanC2017 < -80 || meanC2017 > 80 || meanC2018 < -80 || meanC2018 > 80) {
      console.log('Calculation failure: implausible temperature range.');
      console.log('C3: Calculation Failure');
      console.log('C3');
      return;
    }

    // Print concise evidence (<=20 lines)
    const maskedPct2017 = total2017 > 0 ? ((1 - valid2017 / total2017) * 100) : null;
    const maskedPct2018 = total2018 > 0 ? ((1 - valid2018 / total2018) * 100) : null;

    console.log('Region: 30-mile radius around Kabul, Afghanistan');
    console.log(`2017 Feb Source: ${feb2017.source}, Images: ${feb2017.images}, ValidPx: ${valid2017}/${total2017} (${(100 - maskedPct2017).toFixed(1)}% kept), Mean LST: ${meanC2017.toFixed(2)} °C`);
    console.log(`2018 Feb Source: ${feb2018.source}, Images: ${feb2018.images}, ValidPx: ${valid2018}/${total2018} (${(100 - maskedPct2018).toFixed(1)}% kept), Mean LST: ${meanC2018.toFixed(2)} °C`);
    console.log(`Difference (2018 - 2017): ${(meanC2018 - meanC2017).toFixed(2)} °C`);

    // Final Answer
    if (meanC2018 > meanC2017) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('D: Error', err);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
